'use strict';
const crypto = require('crypto');

// Flag types the platform knows about, mapped to their visible prefix.
// Object.freeze + Object.hasOwn() lookups stop inputs like "__proto__" or
// "constructor" from being treated as valid types.
const FLAG_TYPES = Object.freeze({ user: 'LAB_USER', root: 'LAB_ROOT' });

// Session IDs are generated by us, so we can be strict about their shape.
// This regex is also what keeps attacker-controlled path params out of
// filesystem paths and container names (no "../", no spaces, no shell chars).
const SESSION_ID_RE = /^sess_[0-9a-f]{32}$/;

/** LAB_ROOT{<32 hex chars>} -> 16 random bytes = 128 bits from the OS CSPRNG. */
function generateFlag(prefix) {
  return `${prefix}{${crypto.randomBytes(16).toString('hex')}}`;
}

/** The session ID doubles as a bearer handle, so it also gets 128 random bits. */
function generateSessionId() {
  return `sess_${crypto.randomBytes(16).toString('hex')}`;
}

/**
 * Keyed hash of a flag, bound to (session, type).
 * - HMAC with a server-side pepper: a leaked database cannot be used to
 *   brute-force or verify flag guesses without the pepper.
 * - Binding sessionId + flagType into the MAC input means the stored value for
 *   Session A can never equal the stored value for Session B, even if two
 *   plaintext flags somehow collided (defence in depth on top of the
 *   session-scoped lookup).
 * - The value goes last so newline-delimited fields stay unambiguous.
 */
function hmacFlag(pepper, sessionId, flagType, value) {
  return crypto
    .createHmac('sha256', pepper)
    .update(`${sessionId}\n${flagType}\n${value}`)
    .digest('hex');
}

/** Constant-time comparison of two hex digests. */
function hashesMatch(aHex, bHex) {
  const a = Buffer.from(String(aHex), 'hex');
  const b = Buffer.from(String(bHex), 'hex');
  // timingSafeEqual throws on unequal lengths, so check first. Length is not
  // secret (always 32 bytes for a real digest), so this leaks nothing useful.
  if (a.length === 0 || a.length !== b.length) return false;
  return crypto.timingSafeEqual(a, b);
}

/** Constant-time string comparison (used for the optional admin token). */
function safeEqualStrings(a, b) {
  const ha = crypto.createHash('sha256').update(String(a)).digest();
  const hb = crypto.createHash('sha256').update(String(b)).digest();
  return crypto.timingSafeEqual(ha, hb);
}

module.exports = {
  FLAG_TYPES,
  SESSION_ID_RE,
  generateFlag,
  generateSessionId,
  hmacFlag,
  hashesMatch,
  safeEqualStrings,
};
